// backend/routes/assistantRoutes.js
// "Chef Flavo" assistant API.
//   GET  /api/assistant/health  -> { llm: true|false }
//   POST /api/assistant/chat    -> { reply, recipes[] }  (or 503 when no key)
//
// When OPENAI_API_KEY is set the reply is generated by an
// OpenAI-compatible chat model, grounded with real recipes from
// the database so it only recommends dishes that exist on the site.
// When no key is configured we return 503 and the frontend uses its
// built-in offline assistant instead.

const router = require('express').Router();
const Recipe = require('../models/Recipe');

const LLM_KEY = () => process.env.OPENAI_API_KEY || '';
const LLM_MODEL = () => process.env.OPENAI_MODEL || 'gpt-4o-mini';
const LLM_BASE = () => (process.env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/$/, '');

// Report whether the LLM is configured (frontend probes this on first use).
router.get('/health', (req, res) => {
  res.json({ llm: !!LLM_KEY() });
});

// Pull a small, relevant slice of the catalog to ground the model.
async function findRelevantRecipes(message) {
  const words = String(message || '')
    .toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
    .filter(w => w.length > 2).slice(0, 8);

  let matched = [];
  if (words.length) {
    const rx = words.map(w => new RegExp(w, 'i'));
    matched = await Recipe.find({
      $or: [{ title: { $in: rx } }, { cuisine: { $in: rx } }, { ingredients: { $in: rx } }]
    }).select('title cuisine ingredients').limit(6).lean();
  }
  // A little general context so the model knows the catalog exists.
  const sample = await Recipe.find().select('title cuisine').sort({ createdAt: -1 }).limit(8).lean();
  return { matched, sample };
}

router.post('/chat', async (req, res) => {
  try {
    if (!LLM_KEY()) {
      return res.status(503).json({ error: 'LLM not configured', mode: 'offline' });
    }

    const { message, history } = req.body || {};
    if (!message || typeof message !== 'string') {
      return res.status(400).json({ error: 'A "message" string is required.' });
    }

    const { matched, sample } = await findRelevantRecipes(message);

    const catalog = (matched.length ? matched : sample).map(r => ({
      id: String(r._id),
      title: r.title,
      cuisine: r.cuisine || 'General',
      ingredients: (r.ingredients || []).slice(0, 8)
    }));

    const system = [
      'You are Chef Flavo, the warm, concise cooking assistant for the Flavoriz recipe community website.',
      'You help users: find & recommend recipes, decide what to cook from ingredients they have,',
      'suggest ingredient substitutions and measurement conversions, share short cooking tips,',
      'and explain how to use the site.',
      'Site facts: add a recipe at recipe.html (ingredients & steps go one per line); browse categories via the "Recipes" nav dropdown; profile is profile.html; reset a password from login.html.',
      'When recommending a dish, ONLY use recipes from the provided catalog and link them as markdown: [Title](recipe-detail.html?id=ID).',
      'If nothing in the catalog fits, say so and suggest they add it. Keep answers short (2-5 sentences). Use **bold** sparingly and "- " for lists.'
    ].join(' ');

    const messages = [{ role: 'system', content: system }];
    messages.push({ role: 'system', content: 'Recipe catalog (JSON): ' + JSON.stringify(catalog) });
    if (Array.isArray(history)) {
      history.slice(-8).forEach(m => {
        if (m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string') {
          messages.push({ role: m.role, content: m.content.slice(0, 1500) });
        }
      });
    }
    messages.push({ role: 'user', content: message.slice(0, 2000) });

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);

    let data;
    try {
      const resp = await fetch(LLM_BASE() + '/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + LLM_KEY()
        },
        body: JSON.stringify({
          model: LLM_MODEL(),
          messages,
          temperature: 0.6,
          max_tokens: 400
        }),
        signal: controller.signal
      });
      if (!resp.ok) {
        const detail = await resp.text().catch(() => '');
        console.error('LLM error', resp.status, detail.slice(0, 300));
        return res.status(502).json({ error: 'LLM request failed', mode: 'offline' });
      }
      data = await resp.json();
    } finally {
      clearTimeout(timeout);
    }

    const reply = data && data.choices && data.choices[0] &&
      data.choices[0].message && data.choices[0].message.content;
    if (!reply) return res.status(502).json({ error: 'Empty LLM reply', mode: 'offline' });

    // Return the grounded recipes so the widget can render cards.
    const recipes = matched.slice(0, 4).map(r => ({
      _id: String(r._id), title: r.title, cuisine: r.cuisine, image: r.image
    }));

    res.json({ reply: reply.trim(), recipes });
  } catch (err) {
    console.error('assistant /chat error:', err.message);
    res.status(500).json({ error: 'Assistant error', mode: 'offline' });
  }
});

module.exports = router;
